export async function execSeed() {
  await connectDB();
  await Bundle.deleteMany({}); await Bundle.insertMany(bundles);
  await Channel.deleteMany({}); await Channel.insertMany(channels);
  return { bundles: bundles.length, channels: channels.length };
}

// Only run standalone (npm run seed) — not when imported by adminRoutes.js
if (import.meta.url === `file://${process.argv[1]}`) {
  execSeed()
    .then((result) => {
      console.log(`[seed] Inserted ${result.bundles} bundles, ${result.channels} channels`);
      process.exit(0);
    })
    .catch((err) => { console.error('[seed] Failed:', err); process.exit(1); });
}